from qgis.core import QgsDistanceArea, QgsCoordinateReferenceSystem
da = QgsDistanceArea()
da.setSourceCrs(QgsCoordinateReferenceSystem('EPSG:2154'), project.transformContext())
da.setEllipsoid('WGS84')
stats = {}
for lid, layer in project.mapLayers().items():
    from qgis.core import QgsVectorLayer
    if not isinstance(layer, QgsVectorLayer):
        continue
    if layer.featureCount() == 0:
        continue
    total_area = 0
    for feat in layer.getFeatures():
        geom = feat.geometry()
        if geom and not geom.isEmpty() and geom.type() == 2:
            total_area += da.measureArea(geom)
    if total_area > 0:
        stats[layer.name()] = {
            'features': layer.featureCount(),
            'area_ha': round(total_area / 10000, 1)
        }
result['surface_stats'] = stats
result['success'] = True

from qgis.core import QgsFillSymbol, QgsLineSymbol, QgsSingleSymbolRenderer

styles = [
    (['egetation', 'végétation'], '100,180,80,160', '60,120,40', '60,140,30'),
    (['hydro', 'eau'], '100,160,220,160', '40,80,160', '40,100,200'),
    (['timent'], '180,180,180,180', '120,120,120', '120,120,120'),
]

for lid, layer in project.mapLayers().items():
    from qgis.core import QgsVectorLayer
    if not isinstance(layer, QgsVectorLayer):
        continue
    name_lower = layer.name().lower()
    for keys, fill, outline, line_color in styles:
        if any(k in name_lower for k in keys):
            if layer.geometryType() == 2:
                sym = QgsFillSymbol.createSimple({'color': fill, 'outline_color': outline, 'outline_width': '0.2'})
            elif layer.geometryType() == 1:
                sym = QgsLineSymbol.createSimple({'color': line_color, 'width': '0.6'})
            else:
                continue
            layer.setRenderer(QgsSingleSymbolRenderer(sym))
            layer.triggerRepaint()
            break

result['success'] = True
